import*as THREE from'three';import{Module,materials}from'../../core/index.js';import{mesh}from'../../modeling/parts.js';
const tau=Math.PI*2;function annulus(parent,outer,inner,len,y,m,n){const s=new THREE.Shape();s.absarc(0,0,outer,0,tau,false);const h=new THREE.Path();h.absarc(0,0,inner,0,tau,false);s.holes.push(h);const g=new THREE.ExtrudeGeometry(s,{depth:len,bevelEnabled:false,curveSegments:48}).rotateX(-Math.PI/2);return mesh(parent,g,m,[0,y,0],n);}
/** Own supplied433 SMA-male110mm rubber duck,static observed folded pose.No hinge-axis claim. */
export class Antenna extends Module{static meta={id:'m5stack.unit.lora-e220-433.antenna',name:'LoRaE220-433 supplied110mm static antenna',sku:'U170-433 accessory',connector:'sma-female',physicalConnector:'sma-male'};build(){const frame=new THREE.Group();frame.name='LoRa433 own static folded110mm antenna';this.body.add(frame);const black=materials.plastic(0x202521,{roughness:.72}),metal=materials.metal(0xaab0a8,{roughness:.43}),gold=materials.metal(0xd4bd58,{roughness:.42}),coupling=annulus(frame,4.6,3.28,8.8,-3.2,black,'LoRa433 antenna actual open receiving coupling sleeve'),inner=annulus(frame,3.27,3.24,4.9,-2.5,metal,'LoRa433 antenna actual recessed female-thread coupling wall'),insulator=annulus(frame,2.6,.3,3.8,1.8,materials.plastic(0xe8e6d7),'LoRa433 antenna actual bored male-contact dielectric');const pin=mesh(frame,new THREE.CylinderGeometry(.24,.24,5.8,32),gold,[0,.1,0],'LoRa433 antenna actual SMA male centre pin');const back=mesh(frame,new THREE.CylinderGeometry(3.7,3.7,9,48),black,[0,10.1,0],'LoRa433 antenna closed connector neck');for(let i=0;i<32;i++){const a=i*tau/32;mesh(frame,new THREE.BoxGeometry(.25,7,.25),black,[Math.sin(a)*4.58,1.2,Math.cos(a)*4.58],'LoRa433 antenna fixed coupling grip rib');}const elbow=mesh(frame,new THREE.SphereGeometry(4.4,40,24),black,[0,17,0],'LoRa433 antenna observed static rounded elbow,no joint');const rod=mesh(frame,new THREE.CylinderGeometry(2.6,3.75,86.4,48).rotateZ(-Math.PI/2),black,[43.2,17,0],'LoRa433 antenna fixed tapered rubber whip');const tip=mesh(frame,new THREE.SphereGeometry(2.6,32,20),black,[86.4,17,0],'LoRa433 antenna rounded closed rubber tip');for(const x of[9.5,13]){const ring=mesh(frame,new THREE.TorusGeometry(3.6,.12,8,40).rotateY(Math.PI/2),black,[x,17,0],'LoRa433 antenna actual fixed rubber collar groove');}this.antennaAssembly={frame,coupling,inner,insulator,pin,back,elbow,rod,tip};}}
